css:
.hero{position:relative; display:grid; grid-template-columns:1fr 39%; background:#fff}
.hero-img{margin:57px 0 70px 36px; width:calc(100% - 36px); height:72vh;
  object-fit:cover; display:block; border-radius:0}
.hero-side{background:#c8a95d; padding:24px 40px}   /* 写真の右辺を食う面 */
.hero .brand{position:absolute; top:18px; left:36px} /* 写真の外の白地に置く */
